#include<stdio.h>

#include<math.h>

int main()

{

    // 声明变量，x0和x1用于迭代计算方程的根，f是方程的值，f1是方程的导数的值

    double x0, x1, f, f1;

    // 初始化x1为1.5，这是根的初始猜测值

    x1 = 1.5;

    // 开始迭代计算

    do

    {

        // 将x1的值赋给x0，因为下一次迭代需要用上一次的x1作为新的x0

        x0 = x1;

        // 计算方程2x^3 - 4x^2 + 3x - 6在x0处的值

        f = 2 * x0 * x0 * x0 - 4 * x0 * x0 + 3 * x0 - 6;

        // 计算方程2x^3 - 4x^2 + 3x - 6的导数(6x^2 - 8x + 3)在x0处的值

        f1 = 6 * x0 * x0 - 8 * x0 + 3;

        // 使用牛顿迭代法公式x1 = x0 - f(x0)/f'(x0)更新x1的值

        x1 = x0 - f / f1;

        // 当x1和x0的差的绝对值大于等于1e-5时，继续迭代

    } while (fabs(x1 - x0) >= 1e-5);

    // 输出方程在1.5附近的根

   printf("此方程在1.5附近的根为%lf", x1);

    return 0;

}



