// 将十六进制字符串转换为十进制整数

int hexToDec(char hex[])

{

    int len = strlen(hex);

    int decimal = 0;

    // 遍历十六进制字符串

    for (int i = 0; i < len; i++)

    {

        char digit = hex[i];

        int value;

        // 根据字符判断其十六进制值

        if (isdigit(digit))

        {

            value = digit - '0';

        }

        else if (digit >= 'a' && digit <= 'f')

        {

            value = digit - 'a' + 10;

        }

        else if (digit >= 'A' && digit <= 'F')

        {

            value = digit - 'A' + 10;

        }

        // 根据位置计算十进制值并累加

        decimal += value * (int)pow(16, len - 1 - i);

    }

    return decimal;

}

