#include <stdio.h>

// 函数声明：交换两个整数的函数

void swap(int* a, int* b);

// 函数声明：冒泡排序函数

void bubbleSort(int arr[], int n);

// 交换两个整数的函数定义

void swap(int* a, int* b)

{

    // 定义临时变量temp，存储*a的值

    int temp = *a;

    // 将*b的值赋给*a

    *a = *b;

    // 将temp（原来*a的值）赋给*b

    *b = temp;

}

// 冒泡排序函数定义

void bubbleSort(int arr[], int n)

{

    // 外层循环，控制比较轮数，每一轮将最大的数“冒泡”到末尾

    for (int i = 0; i < n - 1; i++)

    {

        // 内层循环，控制每一轮中相邻元素的比较和交换

        for (int j = 0; j < n - i - 1; j++)

        {

            // 如果当前元素大于下一个元素，则交换它们

            if (arr[j] > arr[j + 1])

            {

                // 调用swap函数交换相邻元素

                swap(&arr[j], &arr[j + 1]);

            }

        }

    }

}

