void my_strcat(char* dest, char* src);

// 自定义的字符串连接函数定义

void my_strcat(char* dest, char* src)

{

    // 移动指针dest到目标字符串的末尾（即'\0'的位置）

    while (*dest != '\0')

    {

        dest++;

    }

    // 将源字符串src的内容逐个复制到目标字符串dest的末尾

    while (*src != '\0')

    {

        // 将src当前指向的字符复制到dest当前指向的位置

        *dest = *src;

        // 移动dest指针到下一个位置

        dest++;

        // 移动src指针到下一个位置

        src++;

    }

    // 在连接后的字符串末尾添加字符串结束符'\0'

    *dest = '\0';

}


