int n;  // 用于记录学生的数量

// 函数 creat 用于创建一个存储学生信息的链表

struct Student* creat(void)

{

    struct Student* head;  // 链表的头指针

    struct Student* p1, * p2;  // p1 用于创建新节点，p2 用于指向当前链表的最后一个节点

    n = 0;  // 初始化学生数量为 0

    p1 = p2 = (struct Student*)malloc(LEN);  // 为第一个节点分配内存空间

    scanf("%ld,%f", &p1->num, &p1->score);  // 从用户输入中读取学生的学号和分数，注意输

入格式为“学号,分数”

    head = NULL;  // 初始时，头指针置为 NULL

    while (p1->num != 0)

    {  // 当输入的学号不为 0 时，继续添加节点

        n = n + 1;  // 学生数量加 1

        if (n == 1) head = p1;  // 如果是第一个节点，将其设置为头节点

        else p2->next = p1;  // 否则将新节点添加到链表末尾

        p2 = p1;  // p2 指向当前的最后一个节点

        p1 = (struct Student*)malloc(LEN);  // 为下一个节点分配内存空间

        scanf("%ld,%f", &p1->num, &p1->score);  // 继续读取下一个节点的学号和分数

    }

    p2->next = NULL;  // 最后一个节点的 next 指针置为 NULL，结束链表

    return(head);  // 返回链表的头指针

}

int main()

{

    struct Student* pt;  // 定义一个指针用于遍历链表

    pt = creat();  // 调用 creat 函数创建链表

    printf("\nnum\tscore\n");  // 输出表头

    while (pt != NULL)

    {  // 当链表不为空时

        printf("%ld\t%5.1f\n", pt->num, pt->score);  // 输出学生的学号和分数

        pt = pt->next;  // 指针指向下一个节点

    }

    return 0;

}





