// 按成绩从高到低排序

void sortStudents(struct Student stu[], int n) {

    struct Student temp;

    for (int i = 0; i < n - 1; i++) {

        int k = i;

        for (int j = i + 1; j < n; j++) {

            if (stu[j].score > stu[k].score) {

                k = j;

            }

        }

        temp = stu[k];

        stu[k] = stu[i];

        stu[i] = temp;

    }

}

