// 删除特定编号的信息节点

void Delete(struct information** pHead)

{

    int number, flag = 1;

    struct information* p, * q;

   printf("请输入要删除数据的编号: \n");

    scanf("%d", &number);

    p = q = *pHead;

    while (p != NULL && flag)

        if (p->number == number)

        {

            if (p == *pHead)

            {

                *pHead = p->next; free(p);  // 删除头节点

            }

            else

            {

                q->next = p->next; free(p);  // 删除非头节点

            }

            flag = 0;

        }

        else

        {

            q = p; p = p->next;

        }

    if (flag == 1) printf("没有查询到可以删除的数据!\n");

}


